// Controller density index — record JAH-GPCS-MIDIKEYBOARD-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"keys": 25, "pads": 8, "price_usd": 100};
var value = (m.keys*m.pads/m.price_usd*10);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GPCS-MIDIKEYBOARD-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GPCS-MIDIKEYBOARD-000001|' + value.toFixed(2) + ' density index');

